"use client"

import { useState, useEffect } from "react"
import {
  Search,
  ChevronUp,
  ChevronDown,
  AlertCircle,
  Loader2,
  UserCircle,
  RefreshCw,
  Download,
  CheckCircle,
  DollarSign,
  Calendar,
  CreditCard,
  Clock,
  X,
  Info,
} from "lucide-react"
import axios from "axios"
import * as XLSX from "xlsx"
import { jsPDF } from "jspdf"
import Layout from "./Layout"

export default function PaymentTrackingPourSuperadmin() {
  const [searchQuery, setSearchQuery] = useState("")
  const [payments, setPayments] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState("")
  const [sortField, setSortField] = useState("internId.First_Name")
  const [sortDirection, setSortDirection] = useState("asc")
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false)
  const [selectedPayment, setSelectedPayment] = useState(null)
  const [selectedMonths, setSelectedMonths] = useState([])
  const [paymentAmount, setPaymentAmount] = useState(200)
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false)
  const [detailsPayment, setDetailsPayment] = useState(null)

  useEffect(() => {
    fetchPayments()
  }, [])

  const fetchPayments = async () => {
    setIsLoading(true)
    setError("")
    const token = localStorage.getItem("token")

    if (!token) {
      setError("Authentication required. Please log in.")
      setIsLoading(false)
      return
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/payments`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      })
      if (response.data.success) {
        setPayments(response.data.data)
      } else {
        setError("Failed to fetch payments: " + response.data.message)
      }
    } catch (err) {
      setError(`Error fetching payments: ${err.response?.data?.message || err.message}`)
      console.error("Fetch payments error:", err)
    } finally {
      setIsLoading(false)
    }
  }

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc")
    } else {
      setSortField(field)
      setSortDirection("asc")
    }
  }

  const openPaymentModal = (payment) => {
    setSelectedPayment(payment)
    const paidMonths = Object.keys(payment.payments).filter((month) => payment.payments[month] > 0)
    setSelectedMonths(paidMonths)
    setPaymentAmount(200)
    setIsPaymentModalOpen(true)
  }

  const closePaymentModal = () => {
    setIsPaymentModalOpen(false)
    setSelectedPayment(null)
  }

  const openDetailsModal = (payment) => {
    setDetailsPayment(payment)
    setIsDetailsModalOpen(true)
  }

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false)
    setDetailsPayment(null)
  }

  const monthTranslations = {
    September: "Septembre",
    October: "Octobre",
    November: "Novembre",
    December: "Décembre",
    January: "Janvier",
    February: "Février",
    March: "Mars",
    April: "Avril",
    May: "Mai",
    June: "Juin",
    July: "Juillet",
    August: "Août",
  }

  const generateReceiptPDF = (intern, monthsPaid, amount) => {
    const doc = new jsPDF()
    const currentDate = new Date().toLocaleDateString("fr-FR")
    const pageWidth = doc.internal.pageSize.getWidth()
    const margin = 15
    const maxWidth = pageWidth - 2 * margin

    doc.setFillColor(245, 245, 245)
    doc.rect(0, 0, pageWidth, 40, "F")
    doc.setFontSize(20)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Reçu de Paiement", pageWidth / 2, 25, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, 40, pageWidth - margin, 40)

    doc.setFontSize(10)
    doc.setFont("helvetica", "normal")
    doc.setTextColor(100, 100, 100)
    doc.text("HP ISTA Benguérir", pageWidth / 2, 50, { align: "center" })
    doc.text("Hôtel Pédagogique ISTA Benguérir", pageWidth / 2, 57, { align: "center" })
    doc.text("Email: contact@example.com | Téléphone: +212 234 567 890", pageWidth / 2, 64, { align: "center" })

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Détails du Stagiaire", margin, 80)
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")
    doc.text(`Nom: ${intern.internId.First_Name} ${intern.internId.Last_Name}`, margin, 90, { maxWidth })
    doc.text(`CFF: ${intern.internId.CFF}`, margin, 97, { maxWidth })
    doc.text(`Année Académique: ${intern.academicYear}`, margin, 104, { maxWidth })
    doc.setLineWidth(0.2)
    doc.setDrawColor(230, 230, 230)
    doc.line(margin, 110, pageWidth - margin, 110)

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.text("Détails du Paiement", margin, 125)
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")

    doc.setFillColor(230, 230, 230)
    doc.rect(margin, 135, maxWidth, 10, "F")
    doc.setTextColor(33, 37, 41)
    doc.text("Mois", margin + 5, 142)
    doc.text("Montant (DH)", pageWidth - margin - 40, 142, { align: "right" })
    doc.setLineWidth(0.1)
    doc.line(margin, 145, pageWidth - margin, 145)

    let yPos = 155
    monthsPaid.forEach((month) => {
      doc.text(monthTranslations[month], margin + 5, yPos)
      doc.text(`${amount.toFixed(2)}`, pageWidth - margin - 40, yPos, { align: "right" })
      doc.line(margin, yPos + 5, pageWidth - margin, yPos + 5)
      yPos += 12
    })

    doc.setFontSize(12)
    doc.setFont("helvetica", "bold")
    doc.text("Montant Total", margin + 5, yPos + 10)
    doc.setFont("helvetica", "normal")
    doc.text(`${(amount * monthsPaid.length).toFixed(2)} DH`, pageWidth - margin - 40, yPos + 10, { align: "right" })
    doc.setLineWidth(0.3)
    doc.line(margin, yPos + 15, pageWidth - margin, yPos + 15)

    doc.setFontSize(9)
    doc.setTextColor(100, 100, 100)
    doc.text("Merci pour votre paiement!", pageWidth / 2, pageWidth - 20, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, pageWidth - 30, pageWidth - margin, pageWidth - 30)

    doc.save(`Reçu_${intern.internId.First_Name}_${intern.internId.Last_Name}_${currentDate}.pdf`)
  }

const exportDetailsToPDF = (payment) => {
    // Define all 12 months including August
    const months = [
      "September", "October", "November", "December", 
      "January", "February", "March", "April", 
      "May", "June", "July", "August"
    ];

    const monthTranslations = {
      "September": "Septembre",
      "October": "Octobre",
      "November": "Novembre",
      "December": "Décembre",
      "January": "Janvier",
      "February": "Février",
      "March": "Mars",
      "April": "Avril",
      "May": "Mai",
      "June": "Juin",
      "July": "Juillet",
      "August": "Août"
    };

    const doc = new jsPDF()
    const currentDate = new Date().toLocaleDateString("fr-FR")
    const pageWidth = doc.internal.pageSize.getWidth()
    const margin = 15
    const maxWidth = pageWidth - 2 * margin

    doc.setFillColor(245, 245, 245)
    doc.rect(0, 0, pageWidth, 40, "F")
    doc.setFontSize(20)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Détails des Paiements", pageWidth / 2, 25, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, 40, pageWidth - margin, 40)

    // Removed the HP ISTA Benguérir contact information section

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Informations du Stagiaire", margin, 60) // Adjusted y-position from 80 to 60
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")
    doc.text(`Nom: ${payment.internId.First_Name} ${payment.internId.Last_Name}`, margin, 70, { maxWidth }) // Adjusted y-positions
    doc.text(`CFF: ${payment.internId.CFF}`, margin, 77, { maxWidth })
    doc.text(`Année Académique: ${payment.academicYear}`, margin, 84, { maxWidth })
    doc.text(`Total Payé: ${payment.totalAmount} DH`, margin, 91, { maxWidth })
    doc.text(
      `Mois Payés: ${Object.keys(payment.payments).filter((month) => payment.payments[month] >= 0).length}/${
        months.length
      }`,
      margin,
      98,
      { maxWidth }
    )
    doc.setLineWidth(0.2)
    doc.setDrawColor(230, 230, 230)
    doc.line(margin, 105, pageWidth - margin, 105) // Adjusted y-position

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.text("Historique des Paiements", margin, 120) // Adjusted y-position
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")

    doc.setFillColor(230, 230, 230)
    doc.rect(margin, 130, maxWidth, 10, "F") // Adjusted y-position
    doc.setTextColor(33, 37, 41)
    doc.text("Mois", margin + 5, 137) // Adjusted y-position
    doc.text("Montant (DH)", margin + 80, 137)
    doc.text("Statut", margin + 130, 137)
    doc.setLineWidth(0.1)
    doc.line(margin, 140, pageWidth - margin, 140) // Adjusted y-position

    let yPos = 150 // Adjusted starting y-position
    months.forEach((month) => {
      const isPaid = payment.payments[month] > 0
      doc.text(monthTranslations[month], margin + 5, yPos)
      doc.text(isPaid ? `${payment.payments[month].toFixed(2)}` : "-", margin + 80, yPos)
      doc.text(isPaid ? "Payé" : "En Attente", margin + 130, yPos)
      doc.line(margin, yPos + 5, pageWidth - margin, yPos + 5)
      yPos += 12
    })

    if (payment.observation) {
      doc.setFontSize(14)
      doc.setFont("helvetica", "bold")
      doc.text("Observation", margin, yPos + 15)
      doc.setFontSize(11)
      doc.setFont("helvetica", "normal")
      doc.text(payment.observation, margin, yPos + 25, { maxWidth })
      yPos += 35
    }

    doc.setFontSize(9)
    doc.setTextColor(100, 100, 100)
    doc.text(`Date Actuelle: ${currentDate}`, margin, yPos + 20, { maxWidth })
    doc.text(`Créé: ${new Date(payment.createdAt).toLocaleString("fr-FR")}`, margin, yPos + 27, { maxWidth })
    doc.text(`Mis à jour: ${new Date(payment.updatedAt).toLocaleString("fr-FR")}`, margin, yPos + 34, { maxWidth })
    doc.text(`Exporté le: ${currentDate}`, margin, yPos + 41, { maxWidth })
    doc.text("Généré par le Système de Suivi des Paiements", pageWidth / 2, yPos + 48, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, yPos + 10, pageWidth - margin, yPos + 10)

    doc.save(`Détails_Paiements_${payment.internId.First_Name}_${payment.internId.Last_Name}_${currentDate}.pdf`)
}

  const handleConfirmPayment = async () => {
    if (selectedMonths.length === 0) {
      setError("Veuillez sélectionner au moins un mois à marquer comme payé.")
      return
    }

    try {
      const token = localStorage.getItem("token")
      const response = await axios.patch(
        `${process.env.REACT_APP_API_URL}/api/payments/${selectedPayment.internId._id}`,
        {
          months: selectedMonths,
          amount: paymentAmount,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      )

      if (response.data.success) {
        fetchPayments()
        const newPaidMonths = selectedMonths.filter(
          (month) => !Object.keys(selectedPayment.payments).includes(month) || selectedPayment.payments[month] === 0
        )
        if (newPaidMonths.length > 0) {
          generateReceiptPDF(selectedPayment, newPaidMonths, paymentAmount)
        }
        closePaymentModal()
      }
    } catch (err) {
      setError("Échec de la mise à jour du paiement: " + (err.response?.data?.message || err.message))
    }
  }

  const filteredAndSortedPayments = payments
    .filter((payment) => {
      if (!payment.internId) return false
      const matchesSearch =
        `${payment.internId.First_Name} ${payment.internId.Last_Name}`
          .toLowerCase()
          .includes(searchQuery.toLowerCase()) || payment.internId.CFF.toLowerCase().includes(searchQuery.toLowerCase())
      return matchesSearch
    })
    .sort((a, b) => {
      if (sortField.includes("internId")) {
        const [parent, child] = sortField.split(".")
        const valueA = a[parent]?.[child]?.toString().toLowerCase() || ""
        const valueB = b[parent]?.[child]?.toString().toLowerCase() || ""
        return sortDirection === "asc" ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA)
      }
      const valueA = a[sortField]?.toString().toLowerCase() || ""
      const valueB = b[sortField]?.toString().toLowerCase() || ""
      return sortDirection === "asc" ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA)
    })

  const handleExportToExcel = () => {
    const exportData = filteredAndSortedPayments.map((payment) => ({
